FUNCTION UNDER TEST:
Name: buffer_compact
Signature: ssize_t buffer_compact(buffer_t *self)
Description: /**
 * @brief Remove unused space from a buffer and reallocate to fit its contents.
 *
 * Shrinks the buffer to match its current logical length, discarding any unused
 * capacity at the end. The buffer's data is copied into a newly allocated region,
 * and the old allocation is freed. If allocation fails, the buffer remains unchanged.
 *
 * @param self Pointer to the buffer to compact. Must not be NULL and must be a valid buffer_t.
 *
 * @return Number of bytes freed (original capacity minus new length) on success,
 *         or -1 if memory allocation fails.
 *
 * @note Memory: The buffer's data pointer is updated to a new allocation.
 * @note Error: Returns -1 on allocation failure; buffer is not modified in this case.
 */
Dependencies: buffer_length

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_compact
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Forward declarations for dependency functions
size_t
buffer_length(buffer_t *self);

// Target function implementation
ssize_t
buffer_compact(buffer_t *self) {
  size_t len = buffer_length(self);
  size_t rem = self->len - len;
  char *buf = calloc(len + 1, 1);
  if (!buf) return -1;
  memcpy(buf, self->data, len);
  free(self->alloc);
  self->len = len;
  self->data = self->alloc = buf;
  return rem;
}

```

